window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-31601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάροχος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1283 na letra π · nº geral 31601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que acompanha os recém-casados no carro nupcial. 〈παρά, ὄχος〉</p></section></article>\n<article id=\"entry-dgp-31602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροψάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1284 na letra π · nº geral 31602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comer algo, ac., com pão.</p></section></article>\n<article id=\"entry-dgp-31603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροψίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1285 na letra π · nº geral 31603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prato de guloseimas ou de entradas 2 prato.</p></section></article>\n<article id=\"entry-dgp-31604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρόψομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1286 na letra π · nº geral 31604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de παροράω.</p></section></article>\n<article id=\"entry-dgp-31605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροψώνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1287 na letra π · nº geral 31605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 iguaria fina 2 tempero 3 encanto. 〈παρά, ὀψωνέω〉</p></section></article>\n<article id=\"entry-dgp-31606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρπεπιθών</h1><div class=\"entry-meta\"><span>DGP · ordem 1288 na letra π · nº geral 31606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 poét. sinc. de παραπείθω.</p></section></article>\n<article id=\"entry-dgp-31607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παρρασική, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1289 na letra π · nº geral 31607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">território da Parrásia, na Arcádia.</p></section></article>\n<article id=\"entry-dgp-31608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παρράσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1290 na letra π · nº geral 31608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da Parrásia ♦ οἱ Παρράσσιοι 2 os habitantes da Parrásia.</p></section></article>\n<article id=\"entry-dgp-31609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1291 na letra π · nº geral 31609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 liberdade de expressão; franqueza: παρρησίαν διδόναι conceder liberdade de falar, παρρησίᾳ φράζειν eur. falar livremente, abertamente 2 licenciosidade de expressão; descaramento; atrevimento 3 faculdade; liberdade: παρρησίαν ἔχειν jos. ter possibilidade de, inf.</p></section></article>\n<article id=\"entry-dgp-31610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησιάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1292 na letra π · nº geral 31610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. παρρησιάσομαι, aor. ἐπαρρησια­σάμην, perf. pas. πεπαρρησίασμαι) 1 falar com toda a liberdade, com franqueza a alguém, dat. ou πρός e ac.; de alguém ou algo, περί e gen.; contra alguém, εἰς e ac. ou κατά e gen. ♦ perf. pas. 2 ser dito francamente: πεπαρρησιασμένος falado com franqueza. 〈παρρησία〉</p></section></article>\n<article id=\"entry-dgp-31611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησιαστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1293 na letra π · nº geral 31611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pessoa franca. 〈παρρησιάζομαι〉</p></section></article>\n<article id=\"entry-dgp-31612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1294 na letra π · nº geral 31612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">franco; sincero. 〈παρρησιάζομαι〉</p></section></article>\n<article id=\"entry-dgp-31613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρστάς</h1><div class=\"entry-meta\"><span>DGP · ordem 1295 na letra π · nº geral 31613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part., παρστήετον 3ª dual subj., formas de aor.2 poét. de παρίστημι.</p></section></article>\n<article id=\"entry-dgp-31614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρτιθεῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 1296 na letra π · nº geral 31614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. ind. ép. de παρατίθημι.</p></section></article>\n<article id=\"entry-dgp-31615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παρυσάτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1297 na letra π · nº geral 31615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Parisatis, rainha persa.</p></section></article>\n<article id=\"entry-dgp-31616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρυφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1298 na letra π · nº geral 31616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acrescentar franja ou orla bordada 2 bordar; tecer 3 superar na arte de bordar, de tecer.</p></section></article>\n<article id=\"entry-dgp-31617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρυφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1299 na letra π · nº geral 31617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 veste com orla de franja 2 faixa de púrpura 3 toga pretexta, em Roma.</p></section></article>\n<article id=\"entry-dgp-31618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρφάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1300 na letra π · nº geral 31618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part., παρφάσθαι inf., formas de pres. méd. poét. de παράφημι.</p></section></article>\n<article id=\"entry-dgp-31619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάρφασις</h1><div class=\"entry-meta\"><span>DGP · ordem 1301 na letra π · nº geral 31619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = παράφασις.</p></section></article>\n<article id=\"entry-dgp-31620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρφυγέειν</h1><div class=\"entry-meta\"><span>DGP · ordem 1302 na letra π · nº geral 31620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor.2 poét.) fugir ao longo ou diante de, dat.</p></section></article>\n<article id=\"entry-dgp-31621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῶ, ῇς, ῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 1303 na letra π · nº geral 31621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. pres. de πάρειμι1 ou subj. aor.2 de παρίημι.</p></section></article>\n<article id=\"entry-dgp-31622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1304 na letra π · nº geral 31622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">compor de modo paródico; parodiar. 〈πα­ρῳδός〉</p></section></article>\n<article id=\"entry-dgp-31623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῳδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1305 na letra π · nº geral 31623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imitação satírica de uma obra poética; paródia. 〈παρῳδός〉</p></section></article>\n<article id=\"entry-dgp-31624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῳδός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1306 na letra π · nº geral 31624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que canta ou se exprime em termos evasivos, i.e., obscuros ♦ ὁ παρῳδός 2 autor de paródia. 〈παρά, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-31625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1307 na letra π · nº geral 31625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. παρωθήσω e παρώσω, aor. πάρωσα) 1 impelir para o lado; mover; afastar; rejeitar 2 desdenhar; desprezar 3 dissimular ♦ méd. 4 repelir para o lado, longe de si 5 repelir duramente; expulsar: π. τινα τιμῆς luc. destituir alguém de um cargo honorífico 6 diferir; adiar.</p></section></article>\n<article id=\"entry-dgp-31626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῳχημένος</h1><div class=\"entry-meta\"><span>DGP · ordem 1308 na letra π · nº geral 31626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. de παροίχομαι.</p></section></article>\n<article id=\"entry-dgp-31627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωκεάνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1309 na letra π · nº geral 31627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que habita ou está situado perto do Oceano. 〈παρά, Ὠκεανός〉</p></section></article>\n<article id=\"entry-dgp-31628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωκεανῖτις, ίτιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1310 na letra π · nº geral 31628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = παρωκεάνις.</p></section></article>\n<article id=\"entry-dgp-31629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῶμμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1311 na letra π · nº geral 31629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. παροράω.</p></section></article>\n<article id=\"entry-dgp-31630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1312 na letra π · nº geral 31630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. de πάρειμι1.</p></section></article>\n<article id=\"entry-dgp-31631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωνυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1313 na letra π · nº geral 31631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semelhança de nome; nome derivado de outro; paronímia 2 jogo de palavras; paronomásia 3 apodo. 〈παρώνυμος〉</p></section></article>\n<article id=\"entry-dgp-31632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωνύμιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1314 na letra π · nº geral 31632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 derivado de um nome ou de uma palavra semelhante ♦ τὸ παρωνύμιον 2 palavra derivada 3 cognome. 〈παρώνυμος〉</p></section></article>\n<article id=\"entry-dgp-31633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρώνυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1315 na letra π · nº geral 31633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem nome semelhante 2 derivado de outra palavra ♦ τὸ παρώνυμον 3 cognome. 〈παρά, ὄνομα〉</p></section></article>\n<article id=\"entry-dgp-31634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωνυχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1316 na letra π · nº geral 31634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">paroníquia; panarício. 〈παρά, ὄνυξ〉</p></section></article>\n<article id=\"entry-dgp-31635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάρωρα</h1><div class=\"entry-meta\"><span>DGP · ordem 1317 na letra π · nº geral 31635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πάρωρος.</p></section></article>\n<article id=\"entry-dgp-31636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάρωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1318 na letra π · nº geral 31636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vem fora de época; intempestivo 2 atrasado; tardio ♦ πάρωρα adv. 3 fora de época.</p></section></article>\n<article id=\"entry-dgp-31637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρωροφίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1319 na letra π · nº geral 31637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">borda saliente de um telhado; cornija. 〈παρά, ὄροφος〉</p></section></article>\n<article id=\"entry-dgp-31638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρώσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1320 na letra π · nº geral 31638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de παρωθέω.</p></section></article>\n<article id=\"entry-dgp-31639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρώφθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1321 na letra π · nº geral 31639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. παροράω.</p></section></article>\n<article id=\"entry-dgp-31640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρῴχηκα, παρῴχημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1322 na letra π · nº geral 31640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. παροίχομαι.</p></section></article>\n<article id=\"entry-dgp-31641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάρωχρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1323 na letra π · nº geral 31641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levemente pálido. 〈παρά, ὠχρός〉</p></section></article>\n<article id=\"entry-dgp-31642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πᾶς, πᾶσα, πᾶν</h1><div class=\"entry-meta\"><span>DGP · ordem 1324 na letra π · nº geral 31642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. παντός, πάσης, παντός 1 no sing., todo; cada; qualquer: οἱ δ’ ἄλκιμον ἦτορ ἔχοντες πρόσσω πᾶς πέτεται hom. cheia de ardor, cada uma [das vespas] voa para frente, πᾶς ἀνήρ sóf. todo homem, πᾶς ἄνθρωπος át. todo ser humano, πᾶς τις ésql. cada um, todo homem, πᾶς ὅστις sóf. todo homem que, πᾶν ὅσον ésql. tudo o que, παντός ἐστι com inf. é dever de cada um, πᾶν τὸ ἐλλεῖπον xen. tudo que falta 2 no sing., cada um de, gen. part.: πᾶς Ἑλλένων sóf. cada um dos gregos, cada grego, τῶν ἀνθρώπων πᾶς d.c. cada homem 3 no sing. e no pl., todo; inteiro; total; completo: πᾶσαι πύλαι hom. as portas inteiras; τὴν φάτνην ἐοῦσαν χαλκέην πᾶσαν her. a manjedoura toda de bronze, πᾶσαν ἀληθείην hom. toda a verdade, πᾶν κράτος sóf. poder total, i.e., o poder máximo, ἐν πάσῃ ἀναρχίᾳ καὶ ἀνομίᾳ plat. em completa anarquia e falta de regras, πάντα εἶναί τινος sóf. ser totalmente dependente de alguém 4 no pl. todos, às vezes com gen. partit.; no dat. pl. masc. para todos; na opinião de todos; segundo o juízo de todos; no dat. pl. fem. (subent. ταῖς ψήφοις), com todos os votos, por unanimidade: πάντες τε θεοὶ πᾶσαί τε θέαιναι hom. todos os deuses e todas as deusas, ἅμα πάντες hom. todos juntos, todos ao mesmo tempo, πάντες ὁμοίως dem. todos igualmente, todos sem exceção, πάντα τα μέλλοντα ésql. todas as coisas futuras, τῶν ἀγαθῶν πάντων xen. de todos os bens, Σαμίων πάντες tuc. todos entre os sâmios, todos os sâmios, πάντες ἄριστοι hom. todos os melhores 5 sem art., para marcar que o subst. sing. é empregado como col. (todo inteiro) ou que o subst. pl. designa o total de um conj.: πᾶσα γῆ tuc. toda a terra, πάντες ἄνθρωποι át. todos os homens que se pode imaginar 6 com art. para marcar a totalidade daquilo que o subst. designa: πᾶσαν τὴν ἀλήθειαν λέγειν tuc. dizer toda a verdade, πᾶν τοὐναντίον át. todo o contrário, τὸ πᾶν o todo, tudo junto, τὰ πάντα o todo ou, na Fil., o universo, ὁ πᾶς ἀριθμός ésql. o número total (de navios), οἱ πάντες ἄνθρωποι xen. a totalidade dos homens, todos os homens juntos, τὰς νέας τὰς πάσας her. a totalidade dos navios, τὸ πᾶν κράτος her. o poder absoluto, τῆς πάσης ἀλογίας pol. o completo absurdo 7 com um num., para indicar total do conjunto numerado ou para marcar uma idéia de variedade; com o art., para reforçar a idéia de conjunto: ἐννέα πάντες hom. todos os nove, sem faltar nenhum, κτήνεα πάντα τρισχίλια her. três mil cabeças de gado de todo o tipo, τριάκοντα τὰς πάσας ἡμέρας tuc. trinta dias no todo, οἱ πάντες ὡς ὀκτωκαίδεκα xen. dezoito ao todo ♦ πᾶν, τὸ πᾶν adv. 8 no todo; totalmente; completamente; absolutamente (= ἐς τὸ πᾶν ésql., τῷ παντί xen.) 9 (tempo) τὸ πᾶν luc. sempre, εἰς τὸ πᾶν com ou sem χρόνου para sempre, διὰ παντός durante todo o tempo, continuamente, sempre 10 todo o possível: περὶ παντὸς ποιεῖσθαι át. estimar acima de tudo, πᾶν ποιεῖν plat. ou π. πράττειν lís. fazer todo o seu possível, ἐς πᾶν κακοῦ ἀφικνεῖσθαι her. alcançar toda a infelicidade possível, a infelicidade extrema, ἐν παντὶ ἀθυμίας εἶναι tuc. estar em um desânimo total, εἰς πᾶν ἀφικνεῖσθαι xen. vir a encontrar-se no maior perigo, διὰ παντός absolutamente, de forma comum, de forma geral ♦ πάντα e τὰ πάντα adv. 11 no todo; sob todos os pontos de vista; sob todas as considerações 12 totalmente; inteiramente; completamente: τὰ πάντα νικᾶν xen. vencer totalmente, com a totalidade dos pontos 13 (tempo) continuamente: τὰ πολλὰ πάντα a maior parte do tempo ♦ τὸ πᾶν e τὰ πάντα subst. 14 τὸ πᾶν o todo; a coisa principal; o importante 15 πάντα todo o possível: πάντα γίγνεσθαι hom. tornar-se toda espécie de coisas, assumir todas as formas, transformar-se em tudo possível; πάντα ou τὰ πάντα εἶναί τινι ser tudo para alguém, i.e., o homem ou a coisa a mais importante.</p></section></article>\n<article id=\"entry-dgp-31643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πᾶσαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1325 na letra π · nº geral 31643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. pl. de πᾶς.</p></section></article>\n<article id=\"entry-dgp-31644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασαμένα</h1><div class=\"entry-meta\"><span>DGP · ordem 1326 na letra π · nº geral 31644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. part. fem. dór. de πάομαι1.</p></section></article>\n<article id=\"entry-dgp-31645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 1327 na letra π · nº geral 31645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. méd. poét. de πατέω1.</p></section></article>\n<article id=\"entry-dgp-31646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσασθαι2</h1><div class=\"entry-meta\"><span>DGP · ordem 1328 na letra π · nº geral 31646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. poét. de πατέομαι.</p></section></article>\n<article id=\"entry-dgp-31647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσασθαι1</h1><div class=\"entry-meta\"><span>DGP · ordem 1329 na letra π · nº geral 31647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. poét. de πάομαι.</p></section></article>\n<article id=\"entry-dgp-31648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασάων</h1><div class=\"entry-meta\"><span>DGP · ordem 1330 na letra π · nº geral 31648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. fem. ép. de πᾶς.</p></section></article>\n<article id=\"entry-dgp-31649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πᾶσι</h1><div class=\"entry-meta\"><span>DGP · ordem 1331 na letra π · nº geral 31649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. de πᾶς e de πᾶν.</p></section></article>\n<article id=\"entry-dgp-31650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασιμέλων, οῦσα, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1332 na letra π · nº geral 31650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que interessa a todos; conhecido de todos; célebre. 〈πᾶς, μέλω〉</p></section></article>\n<article id=\"entry-dgp-31651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πασιφάη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1333 na letra π · nº geral 31651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pasífae, esposa de Minos. 〈πᾶς, φάος〉</p></section></article>\n<article id=\"entry-dgp-31652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1334 na letra π · nº geral 31652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de πάομαι2.</p></section></article>\n<article id=\"entry-dgp-31653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασσαλευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1335 na letra π · nº geral 31653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preso com um prego; pregado. 〈πασσαλεύω〉</p></section></article>\n<article id=\"entry-dgp-31654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασσαλεύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1336 na letra π · nº geral 31654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. πατταλεύω 1 fixar com um prego; pregar algo ou alguém, ac., em algo, dat. ou πρός, ἐπί e dat. 2 penetrar como um prego; transpassar; varar 3 fixar (os olhos). 〈πάσσαλος〉</p></section></article>\n<article id=\"entry-dgp-31655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσσαλος,</h1><div class=\"entry-meta\"><span>DGP · ordem 1337 na letra π · nº geral 31655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. πάτταλος, ου (ὁ) 1 cavilha; prego (para pendurar algo) 2 estaca ou cavilha de madeira para prender os cavalos 3 barra; trave 4 cacete 5 membro viril 6 espeto 7 garrote; mordaça.</p></section></article>\n<article id=\"entry-dgp-31656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασσαλόφι(ν)</h1><div class=\"entry-meta\"><span>DGP · ordem 1338 na letra π · nº geral 31656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de πάσσαλος.</p></section></article>\n<article id=\"entry-dgp-31657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασσάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1339 na letra π · nº geral 31657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part., πάσσασθαι inf., aor. méd. de πατέω2.</p></section></article>\n<article id=\"entry-dgp-31658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσσαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1340 na letra π · nº geral 31658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πάσσαλος.</p></section></article>\n<article id=\"entry-dgp-31659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πασσυδί, πασσυδίᾳ</h1><div class=\"entry-meta\"><span>DGP · ordem 1341 na letra π · nº geral 31659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πανσυδί, πανσυδίᾳ.</p></section></article>\n<article id=\"entry-dgp-31660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1342 na letra π · nº geral 31660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. πάττω (fut. πάσω, aor. ἔπασα, perf. desus.; pas. aor. ἐπάσθην, perf. πέπασμαι) 1 verter; derramar; espalhar algo, ac., sobre algo, dat.: τὰ Δέλφιδος ὄστια πάσσω teócr. espalho os ossos de Délfide 2 bordar algo, ac. 3 recobrir com bordado uma cadeira, ac. ♦ méd. 4 bíbl. recobrir (a cabeça); espargir sobre si (cinzas).</p></section></article>\n<article id=\"entry-dgp-31661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσσων</h1><div class=\"entry-meta\"><span>DGP · ordem 1343 na letra π · nº geral 31661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. παχύς.</p></section></article>\n<article id=\"entry-dgp-31662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παστάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1344 na letra π · nº geral 31662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pórtico (de casa) 2 pórtico com colunas ao redor de um templo 3 templo 4 vestíbulo 5 quarto 6 quarto nupcial 7 leito nupcial. 〈παστός〉</p></section></article>\n<article id=\"entry-dgp-31663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παστέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1345 na letra π · nº geral 31663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de πάσσω.</p></section></article>\n<article id=\"entry-dgp-31664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1346 na letra π · nº geral 31664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 salpicado; bordado ♦ ὁ παστός 2 cortina bordada de leito nupcial 3 leito nupcial 4 quarto nupcial. 〈πάσσω〉</p></section></article>\n<article id=\"entry-dgp-31665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσχα</h1><div class=\"entry-meta\"><span>DGP · ordem 1347 na letra π · nº geral 31665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) 1 Páscoa, festa judaica 2 cordeiro pascal 3 refeição pascal.</p></section></article>\n<article id=\"entry-dgp-31666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1348 na letra π · nº geral 31666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πείσομαι, aor.2 ἔπαθον, perf. πέπονθα) 1 provar; experimentar; vivenciar (impressão, sensação, sentimento eufórico ou disfórico), da parte de alguém, ὑπό e gen. 2 vivenciar um mal (físico ou moral); sofrer; padecer 3 estar doente 4 passar por uma situação, κατά e ac.; experimentar; viver de certo modo, adv. 5 vivenciar uma desgraça, um mal; no part. τί παθών; tendo sofrido o quê?, i.e., o que aconteceu de tão grave? 6 Jur. sofrer uma pena, um castigo (op. a ἀποτίνειν pagar multa) 7 com adv. εὖ ou κακῶς ter uma experiência boa ou má com algo, gen. ou ἐκ e gen.; receber tratamento bom ou mal da parte de alguém, ὑπό e gen. 8 (moral) encontrar-se em certa disposição resultante de impressões e efeitos exteriores; experimentar uma disposição, um sentimento, ac., em relação a alguém, πρός e ac. (e estar sob o domínio deste sentimento, desta disposição); ser tomado de paixão por alguém, πρός e ac. 9 experimentar; sentir algo, ac. (= suceder, acontecer algo a alguém) 1 π. κέδεα hom. vivenciar penas, π. πήματα hom. padecer sofrimentos, καὶ τέρπεαι ἄλγεα πάσχων; hom. e te comprazes em padecer dores? πολλὰ φιλικὰ ἔπαθον ὑπ’ ἐκείνου xen. dele recebi muitas demonstrações de amizade, ὑφ’ ὧν κακὸν οὐδέν πω πέπονθε tuc. dos quais não havia recebido mais nenhum dano 2 παθὼν δέ τε νήπιος ἔγνω hes. o tolo aprende com sofrimento, π. κακά hom. padecer males, π. δύσοιστα ésql. padecer sofrimentos intoleráveis, π. ἀνάξια eur. padecer dores não merecidas, Ὀδυσσεὺς ἐπεπόνθει πρὸς τὴν γυναῖκα arr. Odisseu tinha sofrido por causa da esposa 3 ὁ ἰατρὸς ἀπὸ τοῦ χρώματος λέγει ’τούτου ὁ σπλὴν πέπονθε, τούτου δὲ τὸ ἧπαρ’ arr. o médico, por causa da cor [amarelada] diz: ‘é o baço deste que está doente, mas desse é o fígado’ 4 ὅτι ὑϊκὸν αὐτῷ δοκοίη πάσχειν ὁ Κριτίας xen. [dizia] que Crítias lhe parecia ter a sensação de um leitão, χρῆν καὶ τοὺς ἄλλους ποταμούς… ὁμοίως πάσχειν καὶ κατὰ ταῦτα τῷ Νείλῳ her. os outros rios devem também passar pela mesma situação que a do Nilo 5 τί πάσχεις ar., τί χρῆμα πάσχεις; ar. que mal te atinge? que te acontece de mal? τί γὰρ πάθω; o que vai me acontecer? o que será de mim? (que fazer?), τί ἂν πάθοιμι; luc. o que eu viria a sofrer? τί γὰρ πάθωμεν; her. o que sofreríamos? τί παθόντε λελάσμεθα θούριδος ἀλκῆς; hom. por quê experiência passamos para esquecermo-nos de nossa força e resistência? τί παθόντες γαῖαν ἔδυτε; hom. em razão de que experiência fostes para dentro da terra? ἤν τι πάθω ’γώ ar. se me acontecer uma desgraça, i.e., se eu morrer; εἴ τι πείσονται οἱ Μῆδοι xen. se os medos vivenciarem alguma desgraça, ἤν τι ναῦς πάθῃ eur. se o navio naufragar, ἄν τι πάθῃ dem. se sofrer algum mal, εἴ τι πείσεται ἅδε γᾶ eur. se esta terra vivenciar uma derrota, ἔπαθέ τι πρὶν καταπλεῦσαι δεῦρο lís. morreu antes de navegar de volta para cá 6 πάσχειν lís. sofre uma pena; π. τι πρός τινος, ὑπό τινος, sofrer um castigo ou um prejuízo da parte de alguém, τί ἄξιός εἰμι παθεῖν ἢ ἀποτεῖσαι; plat. que castigo mereço sofrer? ou que multa mereço pagar? 7 εὖ πάσχειν sóf. ser feliz, ser bem tratado, ter sorte, κακῶς πάσχειν estar em uma situação penosa, estar infeliz, κατηγοροῦσιν τῶν μαθητῶν ὡς ἀδικοῦσι σφᾶς αὐτοὺς, εὖ παθόντες ὑπ’ αὐτῶν plat. acusam os discípulos de prejudicá-los, embora deles recebam tratamento correto, λέγοντες ὡς οὐκ ἐπὶ τῷ κακῶς πάσχειν ἐκπεμφθεῖεν tuc. dizendo eles que não foi para receber maus tratos que tinham emigrado, τῶν αὐτοῦ κτεάνων εὖ πασχέμεν teóg. alegrar-se com o que se possui, ἐκ τινος εὖ π. plat. experimentar prazer a partir de algo 8 τοιοῦτόν τί μοι ἐφάνησαν πάθος καὶ οἱ ποιηταὶ πεπονθότες plat. também os poetas deram-me evidências de terem essa tal disposição 9 πάσχω τοῦτο sinto isso, eis o que me acontece, ὅπερ ἂν οἱ πολλοὶ πάθοιεν tuc. exatamente o que a maioria poderia sentir, o que poderia suceder à maioria, ὅπερ νῦν ἐς Λακεδαιμονίους πεπόνθατε tuc. como agora vos sentis em relação ao lacedemônios, τὰ αὐτά τινι πάσχειν xen. sentir a mesma coisa que alguém, ὁ μὴ πάσχων artt. o homem insensível, apático, μοι ἔδοξεν ὁμοιότατον πεπονθέναι ὥσπερ ἂν εἴ τις plat. pareceu-me que sucedia exatamente o mesmo que se alguém, κυβερνήτου ἀγαθοῦ πάθος εἰ πάθοι plat. se ele vivesse a experiência de um bom piloto.</p></section></article>\n<article id=\"entry-dgp-31667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1349 na letra π · nº geral 31667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de πάσσω.</p></section></article>\n<article id=\"entry-dgp-31668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατά</h1><div class=\"entry-meta\"><span>DGP · ordem 1350 na letra π · nº geral 31668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">palavra cita = κτείνω.</p></section></article>\n<article id=\"entry-dgp-31669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παταγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1351 na letra π · nº geral 31669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intr. fazer barulho; retinir; retumbar; (água) marulhar; (pássaros) rumorejar 2 fazer ressoar com um ruído seco, ac. ♦ pas. 3 ressoar com um estrondo. 〈πάταγος〉</p></section></article>\n<article id=\"entry-dgp-31670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάταγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1352 na letra π · nº geral 31670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estrépito; ribombo; fragor; estrondo 2 barulho de dois corpos que se chocam; rangido (de dentes).</p></section></article>\n<article id=\"entry-dgp-31671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παταικοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1353 na letra π · nº geral 31671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imagens de deuses pintadas na popa dos navios fenícios.</p></section></article>\n<article id=\"entry-dgp-31672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάταρα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1354 na letra π · nº geral 31672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Patara, cidade da Lícia.</p></section></article>\n<article id=\"entry-dgp-31673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Παταρεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 1355 na letra π · nº geral 31673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Patara.</p></section></article>\n<article id=\"entry-dgp-31674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάτασσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1356 na letra π · nº geral 31674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. ou 3ª sing. impf. poét. de πατάσσω.</p></section></article>\n<article id=\"entry-dgp-31675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1357 na letra π · nº geral 31675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπάτασσον, fut. πατάξω, aor. ἐπάταξα, perf. desus.; pas. fut. παταχθήσομαι, aor. ἐπατάχθην) 1 dar socos; golpear alguém, ac.: ὁ πατάξαι δεινότατος ἐν μάχῃ εἴτε πυκτικῇ εἴτε τινὶ καὶ ἄλλῃ plat. o mais hábil em golpear numa luta, seja no pugilato, seja numa outra modalidade qualquer 2 fazer palpitar (o coração): πόθος τὴν καρδίαν ἐπάταξε ar. um desejo fez palpitar meu coração 3 intr. (coração) palpitar; bater forte: Ἕκτορι τ’ αὐτῷ θυμὸς ἐνὶ στήθεσσι πάτασσεν hom. no peito de Heitor palpitava-lhe o coração. 〈πάταγος〉</p></section></article>\n<article id=\"entry-dgp-31676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1358 na letra π · nº geral 31676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πατέω.</p></section></article>\n<article id=\"entry-dgp-31677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατέριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1359 na letra π · nº geral 31677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">paizinho. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατέω1-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1360 na letra π · nº geral 31678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. méd. πατέομαι-οῦμαι (aor. ἐπασάμην, perf. πέπασμαι) comer; alimentar-se de; saciar-se de, ac. ou gen. partit.</p></section></article>\n<article id=\"entry-dgp-31679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατέω2-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1361 na letra π · nº geral 31679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calcar aos pés 2 pisotear; tratar com desprezo: τιμάς γε τὰς θεῶν πατῶν sóf. espezinhando as honras devidas aos deuses 3 violar; ultrajar 4 pisar ao caminhar; colocar o pé sobre: π. δωμάτων πύλας ésql. sobre a soleira de uma casa, π. γαῖαν teócr. pisar o solo (de um país) 5 caminhar: π. πρὸς βωμόν ésql. caminhar em direção ao altar. 〈πάτος〉</p></section></article>\n<article id=\"entry-dgp-31680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατήρ</h1><div class=\"entry-meta\"><span>DGP · ordem 1362 na letra π · nº geral 31680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. πατέρος, át. e poét. πατρός, voc. πάτερ, dat. πατέρι, át. e poét. πατρί, gen. πατέρα; pl. nom. πατέρες, gen. πατέρων, dat. πατράσι, gen. πατέρας (ὁ) 1 pai: πατρὸς πατήρ hom. pai do pai, avô 2 pl. os genitores 3 pl. os ancestrais; os antepassados 4 pai, tratamento afetuoso e respeitoso dado aos idosos 5 autor; inventor 6 origem de recurso; capital (de renda).</p></section></article>\n<article id=\"entry-dgp-31681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατησμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1363 na letra π · nº geral 31681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de calcar. 〈πατέω〉</p></section></article>\n<article id=\"entry-dgp-31682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάτμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1364 na letra π · nº geral 31682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Patmos, uma das ilhas Espórades, no mar Egeu.</p></section></article>\n<article id=\"entry-dgp-31683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1365 na letra π · nº geral 31683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passo; marcha 2 caminho percorrido; caminho trilhado: τὰ ἔξω πάτου ὀνόματα luc. as palavras que estão fora da trilha, i.e., fora de uso, obsoletas 3 esterco.</p></section></article>\n<article id=\"entry-dgp-31684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάτρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1366 na letra π · nº geral 31684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pátria 2 descendência; linhagem; raça. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατραγαθία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1367 na letra π · nº geral 31685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">virtude ou mérito do pai ou dos ancestrais. 〈πατήρ, ἀγαθός〉</p></section></article>\n<article id=\"entry-dgp-31686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατραδέλφεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1368 na letra π · nº geral 31686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho ou filha do tio ou da tia paternos; primos. 〈πατήρ, ἀδελφός〉</p></section></article>\n<article id=\"entry-dgp-31687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατραλοίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1369 na letra π · nº geral 31687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que mata o próprio pai; parricida. 〈πατήρ, ἀλοιάω〉</p></section></article>\n<article id=\"entry-dgp-31688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρή</h1><div class=\"entry-meta\"><span>DGP · ordem 1370 na letra π · nº geral 31688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πάτρα.</p></section></article>\n<article id=\"entry-dgp-31689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατριά1, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1371 na letra π · nº geral 31689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 descendência, linhagem, do lado paterno 2 tribo; casta. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρία2</h1><div class=\"entry-meta\"><span>DGP · ordem 1372 na letra π · nº geral 31690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de πάτριος.</p></section></article>\n<article id=\"entry-dgp-31691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατριάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1373 na letra π · nº geral 31691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tard. patriarca, título epicospal 2 bíbl. ancestral. 〈πατριά, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-31692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1374 na letra π · nº geral 31692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do pai; paterno 2 transmitido ou legado pelo pai; hereditário 3 semelhante a um pai; à maneira de um pai; de pai; paternal 4 dos pais; dos ancestrais (instituição, virtude) ♦ ἡ πατρική 5 bens paternos; patrimônio 6 Gram. o caso genitivo. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1375 na letra π · nº geral 31693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como um pai; paternalmente.</p></section></article>\n<article id=\"entry-dgp-31694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάτριος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1376 na letra π · nº geral 31694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 do pai; paterno 2 dos pais; ancestrais; hereditário; tradicional ♦ τὸ πάτριον 3 a regra ou o costume dos ancestrais: πάτριον ἐστί inf., é costume transmitido de pai para filho 4 pl. os costumes; as instituições; as normas dos ancestrais. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1377 na letra π · nº geral 31695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 dos ancestrais 2 da pátria ♦ ἡ πατρίς 3 a terra dos ancestrais; pátria. 〈πατήρ〉</p></section></article>\n<article id=\"entry-dgp-31696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατριώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1378 na letra π · nº geral 31696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 do mesmo país; compatriota 2 do país; nativo 3 tard. cidadão. 〈πατριά〉</p></section></article>\n<article id=\"entry-dgp-31697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατριῶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1379 na letra π · nº geral 31697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) da pátria; do país. 〈πάτριος〉</p></section></article>\n<article id=\"entry-dgp-31698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πατροβᾶς, ᾶ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1380 na letra π · nº geral 31698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Pátrobas, n. de h.</p></section></article>\n<article id=\"entry-dgp-31699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρογένειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1381 na letra π · nº geral 31699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πατρογενής.</p></section></article>\n<article id=\"entry-dgp-31700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατρογενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1382 na letra π · nº geral 31700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido no país; nativo. 〈πατήρ, γένος〉</p></section></article>\n";
